package local.morph.resumecheck;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.webkit.*;import android.widget.*;import android.accessibilityservice.AccessibilityService;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Real task/background tests; no screenshots, fake subscriptions or account mutation. */
public class PhoneResumeInstrumentation extends Instrumentation {
 Activity main,iptv,player;final AtomicReference<Activity> resumed=new AtomicReference<>();
 Object field(Object object,String name)throws Exception{for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
 Object call(Object object,String name)throws Exception{if(Looper.myLooper()!=Looper.getMainLooper()){Object[] value={null};Exception[] error={null};runOnMainSync(()->{try{value[0]=call(object,name);}catch(Exception e){error[0]=e;}});if(error[0]!=null)throw error[0];return value[0];}for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{Method m=c.getDeclaredMethod(name);m.setAccessible(true);return m.invoke(object);}catch(NoSuchMethodException ignored){}throw new NoSuchMethodException(name);}
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 String js(String source)throws Exception{WebView web=(WebView)field(iptv,"web");CountDownLatch done=new CountDownLatch(1);String[] value={null};runOnMainSync(()->web.evaluateJavascript(source,r->{value[0]=r;done.countDown();}));check(done.await(15,TimeUnit.SECONDS),"DOM timeout");return value[0];}
 void restore(Activity expected)throws Exception{check(getUiAutomation().performGlobalAction(AccessibilityService.GLOBAL_ACTION_HOME),"Minimize via Home");long homeUntil=SystemClock.uptimeMillis()+6000;while(SystemClock.uptimeMillis()<homeUntil){android.view.accessibility.AccessibilityNodeInfo home=getUiAutomation().getRootInActiveWindow();if(home!=null&&String.valueOf(home.getPackageName()).contains("launcher"))break;Thread.sleep(50);}Thread.sleep(600);Intent launcher=getTargetContext().getPackageManager().getLaunchIntentForPackage(getTargetContext().getPackageName());launcher.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);getTargetContext().startActivity(launcher);long until=SystemClock.uptimeMillis()+6000;while(SystemClock.uptimeMillis()<until&&(resumed.get()!=expected||!expected.hasWindowFocus()))Thread.sleep(50);check(resumed.get()==expected&&expected.hasWindowFocus()&&!expected.isFinishing()&&!expected.isDestroyed(),"Reopening from launcher must retain "+expected.getClass().getSimpleName()+", destroyed="+expected.isDestroyed()+", finishing="+expected.isFinishing()+", task="+expected.getTaskId()+", got "+resumed.get()+", topRoot="+(resumed.get()!=null&&resumed.get().isTaskRoot()));}
 View subtitleFile(View view){if(view instanceof TextView){String value=((TextView)view).getText().toString().toLowerCase();if(value.contains("subtitle")&&value.contains("file"))return view;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View found=subtitleFile(group.getChildAt(i));if(found!=null)return found;}}return null;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();android.content.SharedPreferences prefs=getTargetContext().getSharedPreferences("tvmorph-ui",0);Object oldPlayer=prefs.getAll().get("systemVodPlayer"),oldLanguage=prefs.getAll().get("language");ActivityMonitor picker=null;try{
 ((Application)getTargetContext().getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){resumed.set(a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
 main=startActivitySync(new Intent().setClassName(getTargetContext().getPackageName(),"local.cleartv.mobile.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
 iptv=startActivitySync(new Intent().setClassName(getTargetContext().getPackageName(),"local.tvmorph.tv.PhoneIptvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500);js("window.__resumeFixture='retained';true");Bundle progress=new Bundle();progress.putString("stage","library ready mainTask="+main.getTaskId()+" iptvTask="+iptv.getTaskId());sendStatus(1,progress);restore(iptv);check("\"retained\"".equals(js("window.__resumeFixture")),"Library WebView must survive minimize/reopen");
 progress.putString("stage","library restored");sendStatus(1,progress);prefs.edit().putBoolean("systemVodPlayer",false).putString("language","en").commit();
 player=startActivitySync(new Intent().setClassName(getTargetContext().getPackageName(),"local.tvmorph.tv.PlayerActivity").putExtra("phone",true).putExtra("url","http://127.0.0.1:18991/phone291-playback-fixture.mp4").putExtra("name","Local resume fixture").putExtra("live",false).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
 long until=SystemClock.uptimeMillis()+20000;while(SystemClock.uptimeMillis()<until&&!Boolean.TRUE.equals(field(player,"prepared")))Thread.sleep(50);check(Boolean.TRUE.equals(field(player,"prepared")),"Local video prepares");Class<?> palette=Class.forName("local.tvmorph.tv.PlayerPalette",true,getTargetContext().getClassLoader());Method light=palette.getDeclaredMethod("daylight",Context.class);light.setAccessible(true);check(Boolean.TRUE.equals(light.invoke(null,player)),"Native player uses the saved light appearance");Method color=palette.getDeclaredMethod("text",Context.class);color.setAccessible(true);check(((Integer)color.invoke(null,player))==0xff193352,"Native player has high contrast navy text");Object chrome=field(player,"cinemaChrome");android.view.View top=(android.view.View)field(chrome,"top"),dock=(android.view.View)field(chrome,"bottom");check(top.getBackground() instanceof android.graphics.drawable.ColorDrawable&&((android.graphics.drawable.ColorDrawable)top.getBackground()).getColor()==android.graphics.Color.TRANSPARENT,"Phone header has no solid background");check(dock.getBackground() instanceof android.graphics.drawable.ColorDrawable&&((android.graphics.drawable.ColorDrawable)dock.getBackground()).getColor()==android.graphics.Color.TRANSPARENT,"Phone playback dock has no solid background");android.widget.LinearLayout tools=(android.widget.LinearLayout)field(chrome,"tools");float density=player.getResources().getDisplayMetrics().density;check(tools.getChildCount()>=4&&tools.getChildAt(0).getWidth()>=Math.round(48*density),"Top player actions have at least 48dp touch targets");check(Boolean.TRUE.equals(field(tools.getChildAt(0),"videoOverlay")),"Player actions use white video overlay ink");Thread.sleep(800);Object video=field(player,"video");check((Integer)call(video,"getDuration")>30000,"Use a long local video fixture");check(Boolean.TRUE.equals(call(video,"isPlaying")),"Video starts");int before=(Integer)call(video,"getCurrentPosition");restore(player);until=SystemClock.uptimeMillis()+2500;while(SystemClock.uptimeMillis()<until&&!Boolean.TRUE.equals(call(video,"isPlaying")))Thread.sleep(30);try{Object exo=field(video,"exo");progress.putString("stage","resume diagnostic: phone="+field(player,"phoneMode")+", requested="+field(player,"phonePlayRequested")+", focus="+player.hasWindowFocus()+", active="+(field(player,"active")==player)+", exo="+(exo!=null)+", ready="+(exo==null?"-":call(exo,"getPlayWhenReady"))+", suppression="+(exo==null?"-":call(exo,"getPlaybackSuppressionReason"))+", playback="+(exo==null?"-":call(exo,"getPlaybackState")));sendStatus(1,progress);}catch(Exception ignored){}check(Boolean.TRUE.equals(call(video,"isPlaying")),"Playing video resumes on return: prepared="+field(player,"prepared")+", intent="+field(player,"resumeOnReturn")+", adhan="+field(player,"adhanPaused")+", position="+call(video,"getCurrentPosition")+", duration="+call(video,"getDuration")+", completed="+field(player,"completed"));check((Integer)call(video,"getCurrentPosition")>=before-1000,"Video position is retained");
 runOnMainSync(()->{player.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_MEDIA_PAUSE));player.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_MEDIA_PAUSE));});check(!Boolean.TRUE.equals(call(video,"isPlaying")),"Manual pause works");restore(player);check(!Boolean.TRUE.equals(call(video,"isPlaying")),"Manual pause stays paused after return");
 progress.putString("stage","playing and paused player restored");sendStatus(1,progress);runOnMainSync(()->{try{call(player,"openSubtitlesMenu");}catch(Exception e){throw new RuntimeException(e);}});View panel=(View)field(player,"rightPanel");check(panel.getVisibility()==View.VISIBLE,"Subtitle menu visible");View upload=subtitleFile(panel);check(upload!=null,"Subtitle menu offers a subtitle file");while(!upload.hasOnClickListeners()&&upload.getParent() instanceof View)upload=(View)upload.getParent();final View file=upload;runOnMainSync(()->file.performClick());long pickerUntil=SystemClock.uptimeMillis()+5000;android.view.accessibility.AccessibilityNodeInfo root=null;while(SystemClock.uptimeMillis()<pickerUntil){root=getUiAutomation().getRootInActiveWindow();if(root!=null&&String.valueOf(root.getPackageName()).contains("documentsui"))break;Thread.sleep(100);}check(root!=null&&String.valueOf(root.getPackageName()).contains("documentsui"),"Subtitle action opens Android's real document picker");getUiAutomation().performGlobalAction(AccessibilityService.GLOBAL_ACTION_BACK);Thread.sleep(350);
 runOnMainSync(()->{try{call(player,"hideRightPanel");}catch(Exception e){throw new RuntimeException(e);}player.onBackPressed();if(!player.isFinishing())player.onBackPressed();});until=SystemClock.uptimeMillis()+4000;while(SystemClock.uptimeMillis()<until&&resumed.get()!=iptv)Thread.sleep(30);check(resumed.get()==iptv,"Back from player returns to same library, got "+resumed.get());check("\"retained\"".equals(js("window.__resumeFixture")),"Library state survives player return");
 result.putString("result","PASS actual phone library and player survive Home and launcher reopen; playing position resumes; manual pause retained; Back returns to same WebView; subtitle menu opens document picker. No screenshots/account changes.");result.putBoolean("passed",true);
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(picker!=null)removeMonitor(picker);android.content.SharedPreferences.Editor edit=prefs.edit();if(oldPlayer==null)edit.remove("systemVodPlayer");else edit.putBoolean("systemVodPlayer",(Boolean)oldPlayer);if(oldLanguage==null)edit.remove("language");else edit.putString("language",(String)oldLanguage);edit.commit();}finish(result.getBoolean("passed",false)?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
